"""Authored source selections for chapter 3; no learner or review-state mutation."""
import json, math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'stereo-course/shestakov-yaschenko-10-11/chapters/ch3.json'
pi=math.pi

def n(x):
    return str(int(x)) if abs(x-round(x))<1e-9 else ('%.8g'%x).replace('.',',')
def accepted(x):
    s=n(x); return list(dict.fromkeys([s,s.replace(',','.')]))
def point(r,deg,c=(0,0)):
    return [c[0]+r*math.cos(deg*pi/180),c[1]+r*math.sin(deg*pi/180),0]
def model(points,edges,labels=None,views=None):
    return dict(points={k:list(v) for k,v in points.items()},edges=[list(e) for e in edges],labelNames=labels or list(points),planar=True,views={'neutral':{'label':'Исходная конфигурация'},**(views or {})})
def circle(m,r,c=(0,0),prefix='c'):
    for j in range(64):m['points'][f'_{prefix}{j}']=point(r,j*360/64,c)
    m['edges'] += [[f'_{prefix}{j}',f'_{prefix}{(j+1)%64}'] for j in range(64)]
    return m
def polygon(m,names):m['edges'] += [[names[i],names[(i+1)%len(names)]] for i in range(len(names))]
def view(label,segments=(),points=()):return dict(label=label,segments=[list(s) for s in segments],points=list(points))
def st(title,prompt,explanation,reason,view='neutral',value=None,label=None):
    x=dict(title=title,prompt=prompt,explanation=explanation,reason=reason,view=view)
    if value is not None:x['input']=dict(prompt=label or prompt,accepted=accepted(value),feedback='Сверь исходные данные и действие, описанное в этом шаге.')
    return x
lessons=[];theory=[]
def add(section,level,num,part,pages,title,text,goal,value,m,steps,hint,caption=None):
    ans=dict(mode='exact',prompt=goal+' Введи число.',accepted=accepted(value),feedback='Вернись к нужному свойству окружности. Ответ относится к вопросу задачи, а не к промежуточному действию.')
    lessons.append(dict(section=section,level=level,number=num,part=part,pages=pages,title=title,text=text,goal=goal,answer=ans,hint=hint,steps=steps,model=m,caption=caption or 'Модель построена по условию. Дополнительные отрезки выделяются по шагам; длины и углы не измеряй по экрану.'))

# 3.1 A3: central/inscribed angle difference.
for part,d in [('a',25),('b',44)]:
    m=model({'O':[0,0,0],'A':point(5,-d),'B':point(5,d),'C':point(5,180)},[['O','A'],['O','B'],['C','A'],['C','B']],['A','B','C','O'],{
        'central':view('Центральный угол AOB',[['O','A'],['O','B']]),'inscribed':view('Вписанный угол ACB',[['C','A'],['C','B']])})
    circle(m,5)
    add('3.1','A',3,part,[58],'Центральный и вписанный углы',f'Центральный угол на {d}° больше острого вписанного угла, опирающегося на ту же дугу окружности. Найди вписанный угол.','Вписанный угол в градусах.',d,m,[
        st('Назови неизвестный угол','Обозначь вписанный угол через x. Чему равен центральный?','Центральный угол равен 2x. Оба угла опираются на одну дугу.','Вписанный угол равен половине соответствующего центрального угла.','central'),
        st('Запиши разность','Как записать: центральный угол больше вписанного на данное число градусов?',f'2x − x = {d}.','Условие задаёт разность двух углов.','inscribed'),
        st('Найди угол','Упрости левую часть равенства.',f'x = {d}°. Проверка: {2*d}° − {d}° = {d}°; искомый угол острый.','2x − x = x.','inscribed',d,'Вписанный угол (градусы).')], 'Если вписанный угол равен x, то центральный угол на той же дуге равен 2x.')

# 3.1 A16: chord products with exact Euclidean construction.
for part,b,c,d in [('a',8,6,4),('b',3,4,9)]:
    a=c*d/b; ox=(b-a)/2; oy=(c-d)/2;r=math.sqrt(ox*ox+oy*oy+a*b)
    m=model({'A':[-a,0,0],'B':[b,0,0],'C':[0,c,0],'D':[0,-d,0],'M':[0,0,0]},[['A','B'],['C','D']],views={'ab':view('Две части хорды AB',[['A','M'],['M','B']]),'cd':view('Две части хорды CD',[['C','M'],['M','D']])})
    circle(m,r,(ox,oy))
    for p in ['A','B','C','D']: assert math.isclose(math.dist(m['points'][p][:2],(ox,oy)),r)
    add('3.1','A',16,part,[61],'Пересекающиеся хорды',f'Хорды AB и CD окружности пересекаются в точке M. MB = {b} см, MC = {c} см, MD = {d} см. Найди MA.','Длина MA в сантиметрах.',a,m,[
        st('Свяжи части хорд','Какие два произведения равны?','MA · MB = MC · MD. В каждом произведении — части одной хорды.','Теорема о произведениях отрезков пересекающихся хорд.','ab'),
        st('Вычисли известное произведение','Найди MC · MD.',f'{c} · {d} = {c*d}. Поэтому MA · {b} = {c*d}.','Подстановка известных длин.','cd',c*d,'Произведение MC · MD (см²).'),
        st('Выдели MA','На какое число разделить известное произведение?',f'MA = {c*d}/{b} = {n(a)} см.','Чтобы найти неизвестный множитель, произведение делят на известный множитель.','ab',a,'Длина MA (см).')], 'Перемножь части одной хорды и приравняй произведению частей другой.')

# 3.1 A18: perpendicular from center bisects chord.
for part,r,length in [('a',15,18),('b',13,10)]:
    h=length/2;dist=math.sqrt(r*r-h*h)
    m=model({'O':[0,0,0],'A':[-h,dist,0],'B':[h,dist,0],'H':[0,dist,0]},[['A','B']],['O','A','B'],{'half':view('H — середина хорды',[['A','H'],['H','B']],['H']),'right':view('Прямоугольный треугольник OHA',[['O','H'],['H','A'],['A','O']],['H'])})
    circle(m,r)
    add('3.1','A',18,part,[62],'Расстояние от центра до хорды',f'Радиус окружности равен {r} см, длина хорды равна {length} см. Найди расстояние от центра окружности до хорды.','Расстояние от центра до хорды в сантиметрах.',dist,m,[
        st('Проведи перпендикуляр','Опусти OH на хорду AB. Найди AH.',f'Перпендикуляр из центра делит хорду пополам: AH = {length}/2 = {n(h)} см.','Перпендикуляр из центра окружности к хорде проходит через её середину.','half',h,'Длина AH (см).'),
        st('Выбери гипотенузу','Какая сторона прямоугольного треугольника OHA является гипотенузой?',f'OA = {r} — радиус. OH² = OA² − AH² = {r*r} − {n(h*h)} = {n(dist*dist)}.','Теорема Пифагора; OA лежит напротив прямого угла H.','right',dist*dist,'Квадрат длины OH (см²).'),
        st('Извлеки корень','Найди положительную длину OH.',f'OH = √{n(dist*dist)} = {n(dist)} см. Это и есть искомое расстояние.','Расстояние до прямой измеряют по перпендикуляру.','right',dist,'Расстояние OH (см).')], 'Соедини центр с концом хорды и её серединой. Получится прямоугольный треугольник.')

# 3.1 B1: same radius for two chords.
for part,ab,ha,cd,hc in [('a',30,20,40,15),('b',16,15,30,8)]:
    r=math.hypot(ab/2,ha)
    assert math.isclose(r,math.hypot(cd/2,hc))
    m=model({'O':[0,0,0],'A':[-ab/2,ha,0],'B':[ab/2,ha,0],'C':[-cd/2,-hc,0],'D':[cd/2,-hc,0],'H':[0,ha,0],'K':[0,-hc,0]},[['A','B'],['C','D']],['A','B','C','D','O'],{'first':view('Радиус через первую хорду',[['O','H'],['H','A'],['A','O']],['H']),'second':view('Тот же радиус у второй хорды',[['O','K'],['K','C'],['C','O']],['K'])})
    circle(m,r)
    if part=='a':
        text=f'AB и CD — хорды одной окружности. AB = {ab}, CD = {cd}; расстояние от центра до AB равно {ha}. Найди расстояние от центра до CD.';goal='Расстояние от центра до CD.';value=hc
        tail=[st('Рассмотри вторую хорду','Найди половину CD и квадрат расстояния OK.',f'CK = {cd}/2 = {cd//2}. OK² = {n(r*r)} − {cd//2}² = {hc*hc}.','Один и тот же радиус — гипотенуза второго прямоугольного треугольника.','second',hc*hc,'Квадрат расстояния OK.'),st('Заверши вычисление','Найди положительный квадратный корень.',f'OK = √{hc*hc} = {hc}.','Расстояние неотрицательно.','second',hc,'Расстояние OK.')]
    else:
        text=f'AB и CD — хорды одной окружности. AB = {ab}; расстояния от центра до AB и CD равны {ha} и {hc}. Найди CD.';goal='Длина хорды CD.';value=cd
        tail=[st('Найди половину второй хорды','Чему равен квадрат CK?',f'CK² = {n(r*r)} − {hc}² = {n((cd/2)**2)}; CK = {cd//2}.','Теорема Пифагора в прямоугольном треугольнике OKC.','second',cd/2,'Половина хорды CK.'),st('Вернись ко всей хорде','Нужно найти CK или всю CD?',f'CD = 2 · {cd//2} = {cd}.','Перпендикуляр из центра делит хорду пополам.','second',cd,'Длина всей хорды CD.')]
    add('3.1','B',1,part,[63],'Две хорды одной окружности',text,goal,value,m,[st('Найди радиус по первой хорде','Опусти OH на AB. Найди квадрат радиуса.',f'AH = {ab}/2 = {ab//2}; R² = {ab//2}² + {ha}² = {n(r*r)}.','Перпендикуляр из центра делит хорду пополам; затем применяется теорема Пифагора.','first',r*r,'Квадрат радиуса R².')]+tail,'Сначала найди радиус по одной хорде; этот же радиус используй для другой.')

# 3.1 B5: inscribed angles on evenly spaced points.
for part,count,start,end,vertex in [('a',8,1,3,7),('b',9,2,5,9)]:
    pts={f'A{i}':point(5,90-(i-1)*360/count) for i in range(1,count+1)}
    u,v,w=f'A{start}',f'A{end}',f'A{vertex}';ang=(end-start)*180/count
    m=model(pts,[[w,u],[w,v]], [u,v,w],{'arc':view('Дуга между концами угла',points=[u,v]),'angle':view('Вписанный угол',[ [w,u],[w,v] ])});circle(m,5)
    for j in range(count):
        m['points'][f'_tickin{j}']=point(4.86,90-j*360/count);m['points'][f'_tickout{j}']=point(5.14,90-j*360/count);m['edges'].append([f'_tickin{j}',f'_tickout{j}'])
    add('3.1','B',5,part,[64],'Равные дуги и вписанный угол',f'На окружности последовательно отмечены {count} точек A₁, A₂, …, A{count}, делящие окружность на равные дуги. Найди угол A{start}A{vertex}A{end}.','Угол в градусах.',ang,m,[
        st('Одна дуга','Найди градусную меру одной из равных дуг.',f'360°/{count} = {n(360/count)}°.','Вся окружность составляет 360°.','arc',360/count,'Одна дуга (градусы).'),
        st('Дуга, на которую опирается угол','Сколько соседних дуг между концами угла на дуге без его вершины?',f'Между A{start} и A{end} находятся {end-start} равные дуги. Их сумма: {end-start} · {n(360/count)}° = {n(2*ang)}°. Точка A{vertex} на этой дуге не лежит.','Вписанный угол опирается на дугу, не содержащую его вершину.','arc',2*ang,'Дуга под углом (градусы).'),
        st('Половина дуги','Как связаны вписанный угол и его дуга?',f'Искомый угол равен {n(2*ang)}°/2 = {n(ang)}°.','Теорема о вписанном угле.','angle',ang,'Вписанный угол (градусы).')], 'Угол опирается на дугу между его концами, которая не содержит вершину угла.', 'На окружности показаны все равные промежутки; подписаны только три точки искомого угла.')

# 3.1 C1: external touching circles and similarity.
for part,r1,r2,ac,bc in [('a',12,14,6,7),('b',8,10,4,5)]:
    co=ac/(2*r1);si=math.sqrt(1-co*co)
    m=model({'O1':[-r1,0,0],'O2':[r2,0,0],'C':[0,0,0],'A':[-ac*co,-ac*si,0],'B':[bc*co,bc*si,0]},[['A','B']],['A','B','C','O1','O2'],{'centres':view('Центры и точка касания коллинеарны',[['O1','O2']]),'triangles':view('Равнобедренные треугольники',[['O1','A'],['O1','C'],['O2','B'],['O2','C']])})
    a_point=m['points']['A'];b_point=m['points']['B']
    m['points']['_line1']=[a_point[i]+.35*(a_point[i]-b_point[i]) for i in range(3)]
    m['points']['_line2']=[b_point[i]+.35*(b_point[i]-a_point[i]) for i in range(3)]
    m['edges']=[['_line1','_line2']]
    circle(m,r1,(-r1,0),'left');circle(m,r2,(r2,0),'right')
    assert math.isclose(ac/bc,r1/r2)
    if part=='a':
        text='Окружность радиуса 12 см касается внешним образом второй окружности в точке C. Прямая через C пересекает первую окружность в точке A, вторую — в точке B. AC = 6 см, BC = 7 см. Найди радиус второй окружности.';value=r2;goal='Радиус второй окружности в сантиметрах.';last=f'6/7 = 12/R₂. По равенству произведений крест-накрест: 6R₂ = 84; R₂ = 14 см.'
    else:
        text='Окружности радиусов 8 см и 10 см касаются внешним образом в точке C. Прямая через C пересекает первую окружность в точке A, вторую — в точке B. AC = 4 см. Найди BC.';value=bc;goal='Длина BC в сантиметрах.';last='4/BC = 8/10. По равенству произведений крест-накрест: 8 · BC = 40; BC = 5 см.'
    add('3.1','C',1,part,[65],'Касание окружностей и подобие',text,goal,value,m,[
        st('Соедини центры','Почему углы O₁CA и O₂CB равны?','Центры O₁, O₂ и точка касания C лежат на одной прямой. A, C, B тоже лежат на одной прямой. Углы O₁CA и O₂CB — вертикальные.','При внешнем касании точка касания лежит на отрезке между центрами; вертикальные углы равны.','centres'),
        st('Докажи подобие','Сравни треугольники O₁CA и O₂CB.','Оба треугольника равнобедренные: их боковые стороны — радиусы своих окружностей. Углы при C равны, значит равны и соответствующие углы при A и B. Треугольники подобны по двум углам.','Равенство углов при основании равнобедренного треугольника; первый признак подобия.','triangles'),
        st('Сопоставь стороны','Каким сторонам соответствуют AC и BC?',f'AC/BC = R₁/R₂. {last}','У подобных треугольников отношения соответствующих сторон равны.','triangles',value,goal)], 'Соедини центры с точкой касания и с точками A, B. Получатся два подобных равнобедренных треугольника.')

# 3.2 A1 and A2: right triangle circumradius and inradius.
for part,a,b in [('a',8,15),('b',10,24)]:
    hyp=math.hypot(a,b);ri=(a+b-hyp)/2;rc=hyp/2
    for num in [1,2]:
        cen=(a/2,b/2) if num==1 else (ri,ri);r=rc if num==1 else ri
        pts={'C':[0,0,0],'A':[a,0,0],'B':[0,b,0],'O':[*cen,0]}
        m=model(pts,[['A','B'],['B','C'],['C','A']],['A','B','C'],{'hyp':view('Гипотенуза AB',[['A','B']]),'radii':view('Центр и радиусы',[['O','A'],['O','B']] if num==1 else [],['O'])});circle(m,r,cen)
        if num==1:
            steps=[st('Найди гипотенузу','Какую сторону находят по двум катетам?',f'AB² = {a}² + {b}² = {int(hyp*hyp)}.','Теорема Пифагора в прямоугольном треугольнике ABC.','hyp',hyp*hyp,'Квадрат длины AB.'),st('Извлеки корень','Чему равна AB?',f'AB = √{int(hyp*hyp)} = {n(hyp)}.','Длина положительна.','hyp',hyp,'Длина AB.'),st('Возьми половину диаметра','Где центр описанной окружности прямоугольного треугольника?',f'Центр — середина гипотенузы AB; AB является диаметром. R = {n(hyp)}/2 = {n(rc)}.','Описанная окружность прямоугольного треугольника имеет диаметр, равный гипотенузе.','radii',rc,'Радиус R.')]
            desc='описанной около';goal='Радиус описанной окружности.';hint='Гипотенуза прямоугольного треугольника является диаметром его описанной окружности.'
        else:
            area=a*b/2;p=(a+b+hyp)/2
            steps=[st('Найди третью сторону','Чему равна гипотенуза?',f'AB = √({a}² + {b}²) = {n(hyp)}.','Теорема Пифагора.','hyp',hyp,'Длина AB.'),st('Площадь и полупериметр','Найди площадь S и полупериметр p.',f'S = {a} · {b}/2 = {n(area)}. p = ({a} + {b} + {n(hyp)})/2 = {n(p)}.','Катеты взаимно перпендикулярны; полупериметр — половина периметра.','neutral',p,'Полупериметр p.'),st('Найди радиус вписанной окружности','Используй S = pr.',f'r = S/p = {n(area)}/{n(p)} = {n(ri)}.','Площадь треугольника равна произведению полупериметра на радиус вписанной окружности.','radii',ri,'Радиус r.')]
            desc='вписанной в';goal='Радиус вписанной окружности.';hint='Вычисли площадь и полупериметр; для вписанной окружности S = pr.'
        add('3.2','A',num,part,[66],('Описанная' if num==1 else 'Вписанная')+' окружность прямоугольного треугольника',f'В треугольнике ABC AC = {a}, BC = {b}, угол C равен 90°. Найди радиус окружности, {desc} этот треугольник.' if num==2 else f'В треугольнике ABC AC = {a}, BC = {b}, угол C равен 90°. Найди радиус окружности, описанной около этого треугольника.',goal,r,m,steps,hint)

# 3.2 A13: tangent lengths.
for part,x,y,z in [('a',4,6,3),('b',5,2,4)]:
    ab=x+y;bc=y+z;ac=x+z;cx=(ac*ac+ab*ab-bc*bc)/(2*ab);cy=math.sqrt(ac*ac-cx*cx);per=ab+bc+ac
    ix=(ac*ab+ab*cx)/per;iy=ab*cy/per
    pts={'A':[0,0,0],'B':[ab,0,0],'C':[cx,cy,0],'M':[x,0,0],'P':[cx*x/ac,cy*x/ac,0],'K':[ab+(cx-ab)*y/bc,cy*y/bc,0]}
    m=model(pts,[['A','B'],['B','C'],['C','A']],views={'pairs':view('Равные касательные из одной вершины',[['A','M'],['A','P'],['B','M'],['B','K'],['C','K'],['C','P']])});circle(m,iy,(ix,iy))
    giv=f'AP = {x} см, BM = {y} см, CK = {z} см' if part=='a' else f'AM = {x} см, BK = {y} см, CP = {z} см'
    add('3.2','A',13,part,[68],'Равные отрезки касательных',f'Вписанная в треугольник ABC окружность касается AB, BC и AC в точках M, K и P. {giv}. Найди периметр треугольника.','Периметр треугольника в сантиметрах.',per,m,[
        st('Сравни касательные','Какие отрезки выходят из одной вершины?',f'AM = AP = {x}; BM = BK = {y}; CK = CP = {z}.','Отрезки касательных из одной точки к окружности равны.','pairs'),st('Собери стороны','Из каких двух отрезков состоит каждая сторона?',f'AB = {x} + {y} = {ab}; BC = {y} + {z} = {bc}; AC = {x} + {z} = {ac}.','Длина отрезка равна сумме длин его частей.','pairs'),st('Сложи три стороны','Найди периметр.',f'P = {ab} + {bc} + {ac} = {per} см. Можно также взять 2 · ({x} + {y} + {z}).','Периметр треугольника — сумма его сторон.','neutral',per,'Периметр P (см).')], 'Из каждой вершины к окружности проведены два равных отрезка касательных.')

# 3.2 B1: extended sine law.
for part,b,c,r in [('a',61,89,10),('b',73,77,9)]:
    a=180-b-c;Adeg=2*b+2*a
    m=model({'A':point(r,Adeg),'B':point(r,0),'C':point(r,2*a),'O':[0,0,0]},[['A','B'],['B','C'],['C','A']],['A','B','C'],{'angle':view('Угол A напротив BC',[['A','B'],['A','C']]),'side':view('Сторона BC и радиусы',[['B','C'],['O','B'],['O','C']],['O'])});circle(m,r)
    add('3.2','B',1,part,[68],'Теорема синусов и радиус',f'Углы B и C треугольника ABC равны {b}° и {c}°. Радиус описанной окружности равен {r}. Найди BC.','Длина стороны BC.',r,m,[
        st('Найди угол напротив BC','Какой угол стоит напротив стороны BC?',f'Это угол A. ∠A = 180° − {b}° − {c}° = {a}°.','Сумма углов треугольника равна 180°.','angle',a,'Угол A (градусы).'),st('Запиши теорему синусов','Как связаны BC, угол A и радиус R?',f'BC/sin A = 2R. Поэтому BC = 2 · {r} · sin {a}°.','Расширенная теорема синусов.','side'),st('Подставь синус','Чему равен sin 30°?',f'sin 30° = 1/2. BC = 2 · {r} · 1/2 = {r}.','Табличное значение синуса и сокращение множителя 2.','side',r,'Длина BC.')], 'Сначала найди угол напротив BC; затем используй BC/sin A = 2R.')

# 3.2 B10: bisector to circumcircle.
for part,r in [('a',14),('b',12)]:
    m=model({'A':point(r,200),'B':point(r,20),'C':point(r,140),'M':point(r,80)},[['A','B'],['B','C'],['C','A'],['A','M']],views={'angles':view('AM делит угол A пополам',[['A','B'],['A','M'],['A','C']]),'chords':view('Хорды BM и CM',[['B','M'],['C','M']])});circle(m,r)
    given='CM' if part=='a' else 'BM';seek='BM' if part=='a' else 'CM'
    add('3.2','B',10,part,[70],'Биссектриса и равные хорды',f'Биссектриса угла A треугольника ABC пересекает его описанную окружность второй раз в точке M. {given} = {r} см. Найди {seek}.',f'Длина {seek} в сантиметрах.',r,m,[
        st('Используй биссектрису','Какие два вписанных угла равны?','∠BAM = ∠MAC.','AM — биссектриса угла A.','angles'),st('Сравни дуги и хорды','На какие дуги опираются эти углы?','Равные вписанные углы опираются на равные дуги BM и MC. Равным дугам соответствуют равные хорды: BM = CM.','Теорема о вписанном угле и свойство равных хорд одной окружности.','chords'),st('Перенеси известную длину','Чему равна искомая хорда?',f'{seek} = {given} = {r} см.','Равные отрезки имеют одинаковые длины.','chords',r,f'Длина {seek} (см).')], 'Равные половины угла A опираются на дуги BM и MC.')

# 3.2 C17: perimeter invariant for three tangent circles.
for part,R,page in [('a',14,74),('b',11,75)]:
    r1=.4*R;r2=.3*R;d1=R-r1;d2=R-r2;d12=r1+r2
    x=(d1*d1+d2*d2-d12*d12)/(2*d1);y=math.sqrt(d2*d2-x*x)
    m=model({'O':[0,0,0],'O1':[d1,0,0],'O2':[x,y,0]},[['O','O1'],['O','O2'],['O1','O2']],views={'inside':view('При внутреннем касании — разность радиусов',[['O','O1'],['O','O2']]),'outside':view('При внешнем касании — сумма радиусов',[['O1','O2']])})
    circle(m,R,prefix='outer');circle(m,r1,(d1,0),'one');circle(m,r2,(x,y),'two')
    assert math.isclose(math.dist((d1,0),(x,y)),d12)
    add('3.2','C',17,part,[page],'Периметр через касание трёх окружностей',f'Две окружности касаются друг друга внешним образом и касаются третьей окружности радиуса {R} см внутренним образом. Центры всех трёх окружностей не лежат на одной прямой. Найди периметр треугольника с вершинами в центрах окружностей.','Периметр треугольника центров в сантиметрах.',2*R,m,[
        st('Обозначь неизвестные радиусы','Пусть малые радиусы равны r₁ и r₂. Найди расстояния до центра большой окружности.',f'OO₁ = {R} − r₁; OO₂ = {R} − r₂.','При внутреннем касании расстояние между центрами равно разности радиусов.','inside'),st('Третья сторона','Чему равно O₁O₂?','O₁O₂ = r₁ + r₂.','При внешнем касании расстояние между центрами равно сумме радиусов.','outside'),st('Сложи и сократи','Сложи три стороны. Какие слагаемые уничтожаются?',f'P = ({R} − r₁) + ({R} − r₂) + (r₁ + r₂) = 2 · {R} = {2*R} см. Радиусы r₁ и r₂ сократились.','Определение периметра и приведение подобных слагаемых.','neutral',2*R,'Периметр P (см).')], 'Не нужно вычислять малые радиусы: обозначь их и сложи расстояния между центрами.', 'Показана одна допустимая конфигурация. Малые радиусы не заданы в задаче; доказательство работает для любых допустимых значений.')

# 3.3 A1: same-segment angles in cyclic quadrilateral.
for part,u,v in [('a',39,55),('b',80,34)]:
    ab=(360-2*u-2*v)/2
    pts={name:point(5,deg) for name,deg in zip('ABCD',[0,ab,2*ab,360-2*u])}
    m=model(pts,[],views={'same':view('Углы CAD и CBD опираются на CD',[['A','C'],['A','D'],['B','C'],['B','D']]),'sum':view('BD делит угол ABC',[['B','A'],['B','D'],['B','C']])});polygon(m,list('ABCD'));circle(m,5)
    add('3.3','A',1,part,[75],'Сумма углов у одной вершины',f'Четырёхугольник ABCD вписан в окружность. ∠ABD = {u}°, ∠CAD = {v}°. Найди ∠ABC.','Угол ABC в градусах.',u+v,m,[st('Найди равные углы','Какой угол с вершиной B опирается на ту же дугу CD, что и CAD?',f'∠CBD = ∠CAD = {v}°.','Вписанные углы, опирающиеся на одну дугу, равны.','same',v,'Угол CBD (градусы).'),st('Раздели большой угол','Какие углы составляют ABC?','Диагональ BD лежит внутри угла ABC, поэтому ∠ABC = ∠ABD + ∠DBC.','В выпуклом четырёхугольнике диагональ делит внутренний угол на две части.','sum'),st('Сложи части','Вычисли ∠ABC.',f'∠ABC = {u}° + {v}° = {u+v}°.','Сложение градусных мер частей угла.','sum',u+v,'Угол ABC (градусы).')], 'Углы CAD и CBD опираются на одну дугу CD.')

# 3.3 A3 and A5: incircle of square.
for num,values,page in [(3,[('a',12),('b',3)],75),(5,[('a',80),('b',14)],76)]:
    for part,s in values:
        r=s/2
        m=model({'A':[0,0,0],'B':[s,0,0],'C':[s,s,0],'D':[0,s,0],'O':[r,r,0],'H':[r,0,0],'K':[r,s,0]},[['A','B'],['B','C'],['C','D'],['D','A']],['A','B','C','D','O'],{'diagonal':view('Диагональ квадрата',[['A','C']]),'diameter':view('Диаметр равен стороне',[['H','K']],['H','K']),'radius':view('Радиус — половина стороны',[['O','H']],['H'])});circle(m,r,(r,r))
        if num==3:
            text=f'В квадрат вписана окружность. Диагональ квадрата равна {s}√2 см. Найди радиус окружности.';goal='Радиус окружности в сантиметрах.';value=r
            steps=[st('Свяжи сторону и диагональ','Пусть сторона равна a. Чему равна диагональ?',f'd² = a² + a² = 2a², значит d = a√2.','Теорема Пифагора для половины квадрата.','diagonal'),st('Найди сторону','Раздели данную диагональ на √2.',f'a = ({s}√2)/√2 = {s} см.','При делении одинаковые множители √2 сокращаются.','diagonal',s,'Сторона квадрата (см).'),st('Возьми половину стороны','Как связаны сторона квадрата и радиус вписанной окружности?',f'2r = a; r = {s}/2 = {n(r)} см.','Диаметр между противоположными точками касания равен расстоянию между сторонами квадрата.','radius',r,'Радиус r (см).')]
        else:
            text=f'Найди площадь квадрата, описанного около окружности радиуса {n(r)}.';goal='Площадь квадрата.';value=s*s
            steps=[st('Найди диаметр','Чему равен диаметр?',f'd = 2r = 2 · {n(r)} = {s}.','Диаметр вдвое больше радиуса.','diameter',s,'Диаметр окружности.'),st('Найди сторону квадрата','Сравни сторону квадрата с диаметром.',f'a = d = {s}.','Окружность касается двух противоположных сторон; расстояние между ними равно её диаметру.','diameter'),st('Найди площадь','Возведи сторону квадрата в квадрат.',f'S = a² = {s}² = {s*s}.','Формула площади квадрата.','neutral',s*s,'Площадь квадрата.')]
        add('3.3','A',num,part,[page],'Квадрат и вписанная окружность',text,goal,value,m,steps,'Диаметр вписанной окружности равен стороне квадрата.')

# 3.3 B2: tangential right trapezoid.
for part,h,leg in [('a',10,16),('b',12,18)]:
    diff=math.sqrt(leg*leg-h*h);a=(h+leg+diff)/2;b=(h+leg-diff)/2
    m=model({'A':[0,0,0],'B':[0,h,0],'C':[b,h,0],'D':[a,0,0]},[['A','B'],['B','C'],['C','D'],['D','A']],views={'legs':view('Перпендикулярная и наклонная боковые стороны',[['A','B'],['C','D']]),'bases':view('Сумма оснований',[['A','D'],['B','C']])});circle(m,h/2,(h/2,h/2))
    assert math.isclose(math.dist(m['points']['C'],m['points']['D']),leg)
    value=(h+leg)*h/2
    add('3.3','B',2,part,[80],'Площадь описанной прямоугольной трапеции',f'Боковые стороны прямоугольной трапеции равны {h} см и {leg} см. В трапецию можно вписать окружность. Найди площадь трапеции.','Площадь трапеции в квадратных сантиметрах.',value,m,[st('Выбери высоту','Какая боковая сторона является высотой?',f'Высота равна {h} см. Наклонная боковая сторона длиннее перпендикулярной: она является гипотенузой прямоугольного треугольника.','В прямоугольной трапеции перпендикулярная боковая сторона равна высоте.','legs',h,'Высота трапеции (см).'),st('Найди сумму оснований','Чему равна сумма оснований описанного четырёхугольника?',f'AD + BC = AB + CD = {h} + {leg} = {h+leg} см.','В четырёхугольнике с вписанной окружностью суммы противоположных сторон равны.','bases',h+leg,'Сумма оснований (см).'),st('Вычисли площадь','Умножь полусумму оснований на высоту.',f'S = ({h+leg}/2) · {h} = {n(value)} см².','Формула площади трапеции S = (a + b)h/2.','bases',value,'Площадь S (см²).')], 'Свойство описанного четырёхугольника сразу даёт сумму оснований; каждое основание отдельно искать не нужно.')

# 3.3 B3: rhombus / rectangle from circle conditions.
s=5;hh=s*math.sqrt(3)/2
m=model({'A':[0,0,0],'B':[s,0,0],'C':[1.5*s,hh,0],'D':[.5*s,hh,0]},[['A','B'],['B','C'],['C','D'],['D','A']],views={'opposites':view('Равные противоположные стороны',[['A','B'],['C','D']]),'all':view('Все стороны равны',[['A','B'],['B','C'],['C','D'],['D','A']])});circle(m,hh/2,(.75*s,hh/2))
add('3.3','B',3,'a',[80],'Описанный параллелограмм', 'В параллелограмм вписана окружность. Одна из сторон параллелограмма равна 5 см. Найди его периметр.','Периметр параллелограмма в сантиметрах.',20,m,[st('Сравни суммы сторон','Что даёт существование вписанной окружности?','AB + CD = BC + AD.','В описанном четырёхугольнике суммы противоположных сторон равны.','opposites'),st('Используй параллелограмм','Какие стороны здесь равны попарно?','AB = CD и BC = AD. Поэтому 2AB = 2BC, то есть AB = BC. Параллелограмм — ромб, все стороны равны 5 см.','Свойство противоположных сторон параллелограмма.','all'),st('Найди периметр','Сложи четыре равные стороны.','P = 4 · 5 = 20 см.','Периметр — сумма всех сторон.','all',20,'Периметр P (см).')], 'Вписанная окружность даёт равенство сумм противоположных сторон; у параллелограмма сами противоположные стороны равны.')
w=math.sqrt(33);h=4
m=model({'A':[0,0,0],'B':[w,0,0],'C':[w,h,0],'D':[0,h,0]},[['A','B'],['B','C'],['C','D'],['D','A']],views={'angles':view('Противоположные углы равны и дают 180°',points=['A','C']),'diagonals':view('Диагонали прямоугольника',[['A','C'],['B','D']])});circle(m,3.5,(w/2,h/2))
add('3.3','B',3,'b',[80],'Вписанный параллелограмм','Около параллелограмма, одна из диагоналей которого равна 7 см, описана окружность. Найди вторую диагональ.','Длина второй диагонали в сантиметрах.',7,m,[st('Сравни противоположные углы','Какие два свойства выполняются одновременно?','У параллелограмма противоположные углы равны. У вписанного четырёхугольника их сумма равна 180°.','Свойства параллелограмма и вписанного четырёхугольника.','angles'),st('Определи фигуру','Каким является каждый из равных углов?','Каждый угол равен 180°/2 = 90°. Значит, параллелограмм является прямоугольником.','Определение прямоугольника.','angles',90,'Каждый угол (градусы).'),st('Сравни диагонали','Что известно о диагоналях прямоугольника?','Диагонали прямоугольника равны. Поэтому вторая диагональ тоже равна 7 см.','Свойство диагоналей прямоугольника.','diagonals',7,'Вторая диагональ (см).')], 'Равные противоположные углы параллелограмма должны одновременно давать в сумме 180°.')

# 3.3 C4: equal angles imply concyclicity.
for part,degs in [('a',[0,63,191,297]),('b',[0,74,158,259])]:
    m=model({name:point(5,deg) for name,deg in zip('ABCD',degs)},[],views={'criterion':view('Углы, опирающиеся на один отрезок',[['A','B'],['B','D'],['A','C'],['C','D']] if part=='a' else [['D','B'],['B','C'],['D','A'],['A','C']]),'triangle':view('Вычисли третий угол треугольника',[['B','C'],['C','D'],['D','B']] if part=='a' else [['A','B'],['B','C'],['C','A']])});polygon(m,list('ABCD'));circle(m,5)
    circumference=[e for e in m['edges'] if e[0].startswith('_c')]
    m['edges']=[e for e in m['edges'] if not e[0].startswith('_c')]
    for key in ['criterion','triangle']:
        m['views'][key]['segments'] += circumference
    m['views']['proved']=view('Доказано: четырёхугольник вписан',circumference)
    if part=='a':
        text='В выпуклом четырёхугольнике ABCD углы ABD и ACD равны. ∠DBC = 53°, ∠CDB = 64°. Найди угол при вершине A четырёхугольника.';same='ABD и ACD';chord='AD';opposite='C';seek='A';u,v=53,64;tri='BCD';value=117
    else:
        text='В выпуклом четырёхугольнике ABCD углы DBC и DAC равны. ∠BAC = 42°, ∠BCA = 37°. Найди угол при вершине D четырёхугольника.';same='DBC и DAC';chord='DC';opposite='B';seek='D';u,v=42,37;tri='ABC';value=79
    third=180-u-v
    add('3.3','C',4,part,[81],'Узнай вписанный четырёхугольник',text,f'Угол {seek} в градусах.',value,m,[st('Докажи существование окружности','Как использовать равенство данных углов?',f'Углы {same} опираются на один отрезок {chord}; их вершины лежат по одну сторону от прямой {chord}, поскольку четырёхугольник выпуклый. По обратной теореме о вписанном угле точки A, B, C, D лежат на одной окружности.','Признак принадлежности четырёх точек одной окружности по равным углам, опирающимся на один отрезок.','criterion'),st('Найди противоположный угол',f'Вычисли угол {opposite} в треугольнике {tri}.',f'∠{opposite} = 180° − {u}° − {v}° = {third}°.','Сумма углов треугольника равна 180°.','triangle',third,f'Угол {opposite} (градусы).'),st('Используй сумму 180°',f'Чему равен угол {seek}?',f'∠{seek} = 180° − {third}° = {value}°.','Противоположные углы вписанного четырёхугольника в сумме дают 180°.','proved',value,f'Угол {seek} (градусы).')], 'Сначала докажи, что четырёхугольник можно вписать в окружность; после этого используй сумму противоположных углов.', 'Окружность появляется при разборе. Её существование нужно обосновать в первом шаге, а не считать данным условием.')

# Display explicitly given segments immediately; retain derived auxiliaries in steps.
initial_segments = {
    ('3.1','B',1,'a'): [('O','H')],
    ('3.1','B',1,'b'): [('O','H'),('O','K')],
    ('3.2','B',10,'a'): [('C','M')],
    ('3.2','B',10,'b'): [('B','M')],
    ('3.3','A',1,'a'): [('A','C'),('B','D')],
    ('3.3','A',1,'b'): [('A','C'),('B','D')],
    ('3.3','A',3,'a'): [('A','C')],
    ('3.3','A',3,'b'): [('A','C')],
    ('3.3','B',3,'b'): [('A','C')],
    ('3.3','C',4,'a'): [('A','C'),('B','D')],
    ('3.3','C',4,'b'): [('A','C'),('B','D')],
}
for card in lessons:
    key=(card['section'],card['level'],card['number'],card['part'])
    for segment in initial_segments.get(key,[]):
        if list(segment) not in card['model']['edges']:
            card['model']['edges'].append(list(segment))
        for name in segment:
            if name not in card['model']['labelNames']:
                card['model']['labelNames'].append(name)

# Authored theory companions for the three source subsections.
m=model({'O':[0,0,0],'A':[-4,3,0],'B':[4,3,0],'C':[0,-5,0],'H':[0,3,0],'T':[7,-1,0]},[['A','B']],['A','B','O'],{'angles':view('Одна дуга — центральный и вписанный углы',[['O','A'],['O','B'],['C','A'],['C','B']],['C']),'chord':view('Половина хорды и радиус',[['O','H'],['H','A'],['A','O']],['H']),'tangent':view('Касательная перпендикулярна радиусу',[['O','B'],['B','T']],['T'])});circle(m,5)
theory.append(dict(section='3.1',title='Углы, хорды и касательные: что соединять на рисунке',pages=[58,61,62,63,65],text='Авторская опора к §3.1. Сначала различай центр окружности, вершину вписанного угла и точку касания. Правильный дополнительный отрезок часто сводит задачу к углам или прямоугольному треугольнику.',goal='Выбирать нужное свойство окружности по расположению точек.',hint='У вписанного угла вершина на окружности; у центрального — в её центре.',model=m,caption='В модели радиус равен 5, хорда AB равна 8. Вспомогательные линии включаются отдельно, чтобы не загромождать рисунок.',steps=[st('Два угла на одной дуге','Сравни ∠AOB и ∠ACB.','Вписанный угол ACB вдвое меньше центрального AOB, опирающегося на ту же дугу AB. Вершина C не должна лежать на выбранной дуге AB.','Теорема о вписанном угле.','angles'),st('Расстояние до хорды','Что даёт перпендикуляр OH?','H — середина AB. В модели AH = 4, OA = 5, поэтому OH = √(25 − 16) = 3. В общем случае R² = d² + (l/2)².','Перпендикуляр из центра делит хорду пополам; теорема Пифагора.','chord',3,'Расстояние OH в модели.'),st('Касательная','Какой угол образуют радиус OB и касательная BT?','Угол OBT прямой. Касательная касается окружности в одной точке, а соответствующий радиус перпендикулярен ей.','Свойство касательной к окружности.','tangent',90,'Угол OBT (градусы).'),st('Не смешивай разные произведения','Как записать правило для пересекающихся хорд?','Если AB и CD пересекаются внутри окружности в M, то MA · MB = MC · MD. В одно произведение входят части одной хорды. Это другое правило, чем сумма длин частей.','Теорема о произведениях отрезков пересекающихся хорд.')] ))

m=model({'C':[0,0,0],'A':[6,0,0],'B':[0,8,0],'O':[3,4,0],'I':[2,2,0],'H':[2,0,0]},[['A','B'],['B','C'],['C','A']],['A','B','C','O','I'],{'outer':view('R — расстояние от O до вершин',[['O','A'],['O','B'],['O','C']]),'inner':view('r — перпендикуляр от I к стороне',[['I','H']],['H'])});circle(m,5,(3,4),'outer');circle(m,2,(2,2),'inner')
theory.append(dict(section='3.2',title='Два центра треугольника: описанная и вписанная окружности',pages=[66,67,68,69,70,74,75],text='Авторская опора к §3.2. Описанная окружность проходит через вершины; вписанная касается сторон. Их центры и радиусы обычно различны. На модели прямоугольный треугольник с катетами 6 и 8.',goal='Отличать R от r и выбирать формулу по данным задачи.',hint='До вершин откладывают радиус описанной окружности; до сторон по перпендикуляру — радиус вписанной.',model=m,caption='O — центр описанной окружности, I — центр вписанной. Подсветка помогает рассматривать их по отдельности.',steps=[st('Описанная окружность','Где лежит её центр у прямоугольного треугольника?','Гипотенуза равна √(6² + 8²) = 10. Центр O — её середина; R = 10/2 = 5.','Гипотенуза является диаметром описанной окружности.','outer',5,'Радиус R в модели.'),st('Любой треугольник','Какая формула связывает сторону a и противоположный угол A с R?','a/sin A = 2R, то есть R = a/(2 sin A). Сторона и угол обязательно должны быть противоположными.','Расширенная теорема синусов.','outer'),st('Вписанная окружность','Как связать r с площадью и полупериметром?','S = pr. В модели S = 6 · 8/2 = 24, p = (6 + 8 + 10)/2 = 12, поэтому r = 24/12 = 2.','Разбиение треугольника на три треугольника с общей высотой r.','inner',2,'Радиус r в модели.'),st('Точки касания','Что известно о двух касательных из одной вершины?','Их отрезки до точек касания равны. Поэтому удобно сначала обозначить три длины касательных x, y, z, а затем собрать стороны x + y, y + z, x + z.','Равенство отрезков касательных из одной точки.','inner'),st('Касание окружностей','Когда расстояние между центрами равно сумме, а когда разности радиусов?','При внешнем касании d = R + r; при внутреннем касании d = R − r, где R > r. Это позволяет вычислять стороны треугольника центров без измерения рисунка.','Центры и точка касания лежат на одной прямой.')] ))

m=model({name:point(5,deg) for name,deg in zip('ABCD',[0,65,170,275])},[],views={'opposite':view('Противоположные углы',points=['A','C']),'arcs':view('Углы на одной хорде CD',[['C','A'],['A','D'],['C','B'],['B','D']])});polygon(m,list('ABCD'));circle(m,5)
theory.append(dict(section='3.3',title='Окружность и четырёхугольник: не путай два условия',pages=[75,76,80,81,82],text='Авторская опора к §3.3. У вписанного четырёхугольника вершины лежат на окружности; у описанного окружность касается всех сторон. Первое условие связывает углы, второе — длины сторон.',goal='Распознавать условие и применять соответствующее свойство.',hint='Вершины на окружности — начни с углов. Касание сторон — начни с равных касательных.',model=m,caption='На модели показан вписанный четырёхугольник. Утверждение о суммах сторон относится к другому случаю — окружности, касающейся всех четырёх сторон.',steps=[st('Вписанный четырёхугольник','Что известно о противоположных углах?','∠A + ∠C = 180° и ∠B + ∠D = 180°. Эти углы опираются на дополняющие друг друга дуги окружности.','Теорема о вписанных углах.','opposite'),st('Одна хорда — равные углы','Почему ∠CAD = ∠CBD?','Оба угла опираются на одну дугу CD и имеют вершины на другой дуге. Поэтому их градусные меры равны.','Вписанные углы, опирающиеся на одну дугу, равны.','arcs'),st('Описанный четырёхугольник','Какие длины связывает вписанная окружность?','Если окружность касается всех сторон ABCD, то AB + CD = BC + AD. Доказательство: обозначить пары равных касательных из каждой вершины и сложить их. Для произвольного четырёхугольника обратное утверждение без дополнительных условий не используем.','Равенство отрезков касательных из одной точки.'),st('Квадрат и окружности','Как связаны сторона a, вписанный радиус r и описанный радиус R?','У квадрата a = 2r, диагональ d = a√2, R = d/2 = (a√2)/2. Сначала уточняй, какая из двух окружностей дана.','Диаметр вписанной окружности равен стороне; диаметр описанной — диагонали.'),st('Параллелограмм','Какие частные фигуры получаются?','Если параллелограмм вписан в окружность, он прямоугольник: равные противоположные углы в сумме дают 180°. Если в параллелограмм вписана окружность, он ромб: равенство сумм противоположных сторон даёт равенство соседних сторон.','Свойства параллелограмма в сочетании со свойствами окружности.')] ))

# Structural/math assertions independent of UI.
assert len(lessons)==36
assert len(theory)==3
assert len({(x['section'],x['level'],x['number'],x['part']) for x in lessons})==36
for card in lessons+theory:
    assert len(card['steps'])>=3
    for p in card['model']['points'].values():assert len(p)==3 and all(math.isfinite(v) for v in p)
    for edge in card['model']['edges']:assert len(edge)==2 and all(k in card['model']['points'] for k in edge)
    for step in card['steps']:assert step['view'] in card['model']['views']
OUT.write_text(json.dumps(dict(chapter=3,title='Окружности',theory=theory,lessons=lessons),ensure_ascii=False,indent=2)+'\n')
print('chapter3:',len(lessons),'source variants;',len(theory),'theory companions')
